import config from './config.js';

const $ = (id) => document.getElementById(id);
const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid = () => crypto.randomUUID();
const clone = (value) => JSON.parse(JSON.stringify(value));
const key = 'together-demo-v1';
const live = config.mode === 'live';
let slug = new URLSearchParams(location.search).get('wedding') || config.slug;
let page = 'overview', filter = 'All', search = '', eventFilter = '', state, busy = false, toastTimer, focusedBeforeDialog, dialogGeneration=0;
const views = [['overview','Overview','◫'],['checklist','Checklist','☑'],['guests','Guest list','♧'],['budget','Budget','₹'],['vendors','Vendors','◇'],['events','Events','▦'],['settings','Settings','⚙']];
const today = () => new Date().toLocaleDateString('en-CA');
const date = (d, opts = {}) => d ? new Date(d.slice(0,10)+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',...opts}) : 'Date to be decided';
const eventName = (id) => state.events.find(e => e.id === id)?.name || 'All celebrations';
const money = (value) => new Intl.NumberFormat('en-IN',{style:'currency',currency:state.settings.currency || 'INR',maximumFractionDigits:0}).format(Number(value)||0);
const sample = () => ({
  settings:{id:'settings',lock_version:0,partner_one:'Aanya',partner_two:'Arjun',date:'2027-02-20',venue:'Jaipur, Rajasthan',currency:'INR',budget:2500000},
  tasks:[
    {id:'t1',title:'Book your wedding venue',completed_at:'2026-10-01',due_date:'2026-10-01',assignee:'Aanya',priority:'High',wedding_event_id:'e3',lock_version:0},
    {id:'t2',title:'Shortlist photographers',completed_at:'2026-10-04',due_date:'2026-10-04',assignee:'Arjun',priority:'Normal',wedding_event_id:null,lock_version:0},
    {id:'t3',title:'Finalise the catering menu',completed_at:null,due_date:'2026-10-18',assignee:'Aanya',priority:'High',wedding_event_id:'e3',lock_version:0},
    {id:'t4',title:'Send save-the-date invitations',completed_at:null,due_date:'2026-10-22',assignee:'Arjun',priority:'Normal',wedding_event_id:null,lock_version:0},
    {id:'t5',title:'Plan the sangeet performances',completed_at:null,due_date:'2026-11-01',assignee:'Family',priority:'Normal',wedding_event_id:'e2',lock_version:0},
    {id:'t6',title:'Book rooms for out-of-town guests',completed_at:null,due_date:'2026-11-10',assignee:'Arjun',priority:'Normal',wedding_event_id:null,lock_version:0}],
  guests:[['g1','Riya Sharma','confirmed','Aanya’s side','Vegetarian'],['g2','Kabir Mehta','confirmed','Arjun’s side','No restrictions'],['g3','Priya Kapoor','invited','Aanya’s side','Vegetarian'],['g4','Neha Kapoor','invited','Both','No restrictions'],['g5','Anita Sharma','confirmed','Aanya’s side','Vegetarian'],['g6','Dev Mehta','tentative','Arjun’s side','No restrictions'],['g7','Sana Khan','declined','Both','No restrictions']].map(([id,name,status,side,menu_restrictions])=>({id,name,status,side,menu_restrictions,email:'',phone:'',special_requests:'',lock_version:0,attendances:{e1:status,e2:status,e3:status,e4:status}})),
  budget:[['b1','Venue & accommodation',1100000,400000,'Venue'],['b2','Catering',450000,100000,'Food & drink'],['b3','Photography & film',180000,50000,'Photography'],['b4','Flowers & decor',230000,75000,'Decor'],['b5','Music & entertainment',80000,20000,'Entertainment']].map(([id,name,amount,paid,category])=>({id,name,amount,total:amount,paid,category,pricing_type:'fixed',wedding_event_id:null,lock_version:0})),
  vendors:[['v1','The Rose Garden','Venue','Booked','Contact details to be added'],['v2','Stories by Light','Photography','Booked','Contact details to be added'],['v3','Marigold & Co.','Decor','Shortlisted','Contact details to be added'],['v4','The Spice Table','Catering','Contacted','Contact details to be added']].map(([id,name,category,status,contact])=>({id,name,category,status,contact,notes:'',wedding_event_id:null,lock_version:0})),
  events:[{id:'e1',name:'Mehendi',date:'2027-02-18',start_time:'15:00',venue:'The garden courtyard',notes:'An afternoon of colour, music, and mehendi.',lock_version:0},{id:'e2',name:'Sangeet',date:'2027-02-19',start_time:'19:00',venue:'The grand ballroom',notes:'Bring your dancing shoes.',lock_version:0},{id:'e3',name:'Wedding ceremony',date:'2027-02-20',start_time:'10:00',venue:'The Rose Garden',notes:'The beginning of our forever.',lock_version:0},{id:'e4',name:'Reception',date:'2027-02-20',start_time:'19:00',venue:'The grand ballroom',notes:'Dinner, dancing, and a little magic.',lock_version:0}],
  members:[],user:null,activity:[]
});

function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function modal(title,html){dialogGeneration++;focusedBeforeDialog=document.activeElement;$('dialog-title').textContent=title;$('dialog-body').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function closeModal(){dialogGeneration++;$('dialog').close();focusedBeforeDialog?.focus();}
$('close-dialog').onclick=closeModal;
$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('dialog').addEventListener('close',()=>{if(!$('dialog').open){dialogGeneration++;focusedBeforeDialog?.focus();}});
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is full. Export your data before leaving.');}}
function csrf(){return decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('csrf-token='))?.split('=').slice(1).join('=')||'');}
async function api(path,options={}){
  const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{Accept:'application/json',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),'X-CSRF-TOKEN':csrf(),...options.headers}});
  if(!response.ok){let data={};try{data=await response.json();}catch{}const error=new Error(data.message || data.errors?.join?.(', ') || (response.status===401?'Please sign in to continue.':`Request failed (${response.status}).`));error.status=response.status;throw error;}
  return response.status===204?null:response.json();
}
async function refresh(){if(busy||!live||!state.user||$('dialog').open)return;try{state=await api(encodeURIComponent(slug)+'/planner');render();$('sync-status').textContent='● Shared workspace';}catch(e){$('sync-status').textContent='● Connection interrupted';if(e.status===401){state.user=null;render();}}}
async function change(entity,record,id=null,extras={},remove=false){
  if(busy)return false;busy=true;
  try{
    const old=entity==='settings'?state.settings:state[entity].find(x=>x.id===id);
    if(live){state=await api(encodeURIComponent(slug)+'/planner/'+entity+(id?'/'+encodeURIComponent(id):''),{method:remove?'DELETE':id?'PATCH':'POST',body:JSON.stringify({record,lock_version:old?.lock_version,...extras})});}
    else{
      const next=clone(state);
      if(entity==='settings')next.settings={...next.settings,...record,lock_version:next.settings.lock_version+1};
      else if(remove){next[entity]=next[entity].filter(x=>x.id!==id);if(entity==='events'){['tasks','vendors','budget'].forEach(k=>next[k].forEach(x=>{if(x.wedding_event_id===id)x.wedding_event_id=null;}));next.guests.forEach(x=>delete x.attendances[id]);}}
      else{const value={...old,...record,id:id||uuid(),lock_version:(old?.lock_version??-1)+1};if(entity==='guests')value.attendances={...old?.attendances,...extras.attendances};if(entity==='budget'){value.paid=extras.paid??old?.paid??0;value.total=Number(value.amount)*(value.pricing_type==='per_person'?next.guests.filter(g=>!['declined','considered'].includes(g.status)).length:1);}if(id)next[entity]=next[entity].map(x=>x.id===id?value:x);else next[entity].push(value);}
      next.budget.forEach(b=>{b.total=Number(b.amount)*(b.pricing_type==='per_person'?next.guests.filter(g=>!['declined','considered'].includes(g.status)).length:1);});
      next.activity=[{text:remove?'Removed a '+entity.replace(/s$/,''):'Updated '+(record.title||record.name||'wedding details'),at:new Date().toISOString()},...(next.activity||[])].slice(0,8);state=next;persist();
    }
    render();return true;
  }catch(e){toast(e.message);if(e.status===409){closeModal();busy=false;await refresh();}return false;}finally{busy=false;}
}
function title(name,subtitle){return `<div class="welcome-line"><div><h1 class="page-title">${name}</h1><p class="page-subtitle">${subtitle}</p></div><span class="date-label">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span></div>`;}
function empty(noun){return `<div class="empty"><h3>A fresh start for your ${noun}.</h3><p>Add your first item to bring the plan to life.</p></div>`;}
function badge(status){return `<span class="pill ${['invited','Contacted','High'].includes(status)?'warm':['declined','considered','Shortlisted'].includes(status)?'gray':''}">${escape(status)}</span>`;}
function stats(){const completed=state.tasks.filter(t=>t.completed_at).length;const planned=state.budget.reduce((a,b)=>a+Number(b.total),0);const paid=state.budget.reduce((a,b)=>a+Number(b.paid),0);const confirmed=state.guests.filter(g=>g.status==='confirmed').length;return `<div class="stats"><div class="stat"><div class="stat-top">Checklist progress <span class="stat-icon">☑</span></div><strong>${completed}<small> / ${state.tasks.length} tasks</small></strong><div class="progress"><i style="width:${state.tasks.length?completed/state.tasks.length*100:0}%"></i></div><small>${state.tasks.length-completed} little steps to go</small></div><div class="stat"><div class="stat-top">Wedding budget <span class="stat-icon">₹</span></div><strong>${money(planned)}</strong><small>of ${money(state.settings.budget)} planned</small><div class="progress"><i style="width:${Math.min(100,planned/Math.max(1,Number(state.settings.budget))*100)}%"></i></div></div><div class="stat"><div class="stat-top">Guest list <span class="stat-icon">♧</span></div><strong>${state.guests.length}<small> guests</small></strong><small>${confirmed} confirmed · ${state.guests.filter(g=>['invited','tentative'].includes(g.status)).length} awaiting a reply</small></div><div class="stat"><div class="stat-top">Vendor payments <span class="stat-icon">◇</span></div><strong>${money(paid)}</strong><small>${money(Math.max(0,planned-paid))} remaining to pay</small></div></div>`;}
function taskRow(t){return `<div class="task-row ${t.completed_at?'done':''}"><input type="checkbox" ${t.completed_at?'checked':''} aria-label="Complete ${escape(t.title)}" data-toggle="${escape(t.id)}"><div class="task-content"><b>${escape(t.title)}</b><small>${escape(t.assignee||'Unassigned')} · ${t.due_date?date(t.due_date):'No deadline'}</small></div>${badge(t.priority||'Normal')}<button class="text-button task-documents-button" data-documents="${escape(t.id)}" data-document-entity="tasks" aria-label="Documents for ${escape(t.title)}">Documents${t.documents?.length?' ('+t.documents.length+')':''}</button><button class="text-button" data-edit="tasks" data-id="${escape(t.id)}">Edit</button></div>`;}
function eventRow(e){return `<div class="event-row"><div class="event-date"><b>${date(e.date,{month:undefined})}</b><small>${date(e.date,{day:undefined,month:'short'}).toUpperCase()}</small></div><div class="event-content"><h3>${escape(e.name)}</h3><p>${escape(e.venue||'Venue to be decided')} · ${escape(e.start_time||'Time to be decided')}</p></div><button class="text-button" data-edit="events" data-id="${escape(e.id)}">Edit</button></div>`;}
const botanical=`<svg class="botanical" viewBox="0 0 400 400" aria-hidden="true"><g fill="none" stroke="#577143" stroke-width="2"><path d="M90 430C180 300 290 220 300 30M154 344C80 290 70 232 66 175M210 268C309 290 366 274 402 222M249 219C200 179 185 120 191 57"/><g fill="#577143" stroke="none"><ellipse cx="294" cy="84" rx="15" ry="44" transform="rotate(-17 294 84)"/><ellipse cx="266" cy="126" rx="13" ry="40" transform="rotate(-42 266 126)"/><ellipse cx="322" cy="141" rx="13" ry="41" transform="rotate(38 322 141)"/><ellipse cx="244" cy="176" rx="13" ry="38" transform="rotate(-48 244 176)"/><ellipse cx="306" cy="195" rx="13" ry="37" transform="rotate(44 306 195)"/><ellipse cx="96" cy="236" rx="13" ry="38" transform="rotate(-33 96 236)"/><ellipse cx="138" cy="290" rx="13" ry="38" transform="rotate(-50 138 290)"/><ellipse cx="272" cy="288" rx="12" ry="35" transform="rotate(80 272 288)"/><ellipse cx="341" cy="255" rx="12" ry="35" transform="rotate(62 341 255)"/><ellipse cx="199" cy="119" rx="12" ry="34" transform="rotate(-8 199 119)"/></g></g></svg>`;
function overview(){const days=state.settings.date?Math.ceil((new Date(state.settings.date+'T00:00:00')-new Date(new Date().toDateString()))/86400000):null;return title('Your forever starts here.','A little organisation. A lot of love. Let’s bring your celebrations together.')+`<section class="hero"><div><div class="eyebrow">THE NEXT CHAPTER</div><h2>${escape(state.settings.partner_one||'Your name')} <i>&</i> ${escape(state.settings.partner_two||'Your partner')}</h2><p>Every detail, every celebration, one beautiful journey.</p><div class="hero-details"><span>▦ ${date(state.settings.date,{year:'numeric'})}</span><span>⌖ ${escape(state.settings.venue||'Add your wedding location')}</span><span>♡ ${state.events.length} celebrations</span></div></div>${botanical}<div class="countdown"><strong>${days===null?'—':Math.abs(days)}</strong><span>${days===null?'PICK YOUR DATE':days<0?'DAYS SINCE I DO':'DAYS UNTIL I DO'}</span><small>The best is yet to come.</small></div></section>`+stats()+`<div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>Your next little steps</h2><p>One thing at a time. You’ve got this.</p></div><a class="text-button" href="#checklist">View checklist →</a></div>${state.tasks.filter(t=>!t.completed_at).slice(0,4).map(taskRow).join('')||empty('checklist')}<div class="panel-bottom"><button class="text-button" data-add="tasks">+ Add a task</button></div></section><section class="panel"><div class="panel-heading"><div><h2>A season of celebrations</h2><p>Every occasion deserves its own moment.</p></div><a class="text-button" href="#events">View all →</a></div>${[...state.events].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4).map(eventRow).join('')||empty('events')}</section></div><div class="lower-grid"><section class="note-panel"><span class="flower">✳</span><div><h2>Good things happen together.</h2><p>Bring your partner, family, and planner into the loop.<br>A shared plan makes room for more joy.</p><button class="text-button" data-action="share">Invite your people →</button></div></section><section class="panel"><div class="panel-heading"><h2>${live?'Planning together':'Your recent activity'}</h2><span class="pill gray">${live?'Shared':'Browser demo'}</span></div>${live?`<div class="activity"><span class="avatar">${escape(state.user?.email?.[0]?.toUpperCase()||'U')}</span><div><p>${escape(state.user?.email||'Sign in to get started')}</p><small>Shared changes refresh automatically while this tab is open.</small></div></div>`:(state.activity?.length?state.activity.slice(0,2).map(a=>`<div class="activity"><span class="avatar">D</span><div><p>${escape(a.text)}</p><small>${new Date(a.at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):`<div class="activity"><span class="avatar">✳</span><div><p>Your sample wedding is ready to explore</p><small>Try adding a task or editing an event.</small></div></div>`)}</section></div>`;}
function matches(record){return JSON.stringify(record).toLowerCase().includes(search.toLowerCase());}
function toolbar(entity,placeholder,extra=''){return `<div class="toolbar"><input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${escape(search)}">${extra}<button class="button primary" data-add="${entity}">+ Add ${entity==='budget'?'expense':entity==='tasks'?'task':entity.replace(/s$/,'')}</button></div>`;}
function filters(values){return `<div class="tabs" aria-label="Filter items">${values.map(v=>`<button class="filter ${filter===v?'active':''}" aria-pressed="${filter===v}" data-filter="${v}">${v}</button>`).join('')}</div>`;}
function actions(entity,id){return `<button class="text-button" data-edit="${entity}" data-id="${escape(id)}">Edit</button> <button class="text-button danger" data-delete="${entity}" data-id="${escape(id)}">Remove</button>`;}
function checklist(){const tasks=state.tasks.filter(matches).filter(t=>filter==='All'||filter==='Completed'&&t.completed_at||filter==='To do'&&!t.completed_at);return title('A plan for every little detail.','Share the work, set your deadlines, and celebrate each step forward.')+toolbar('tasks','Search tasks…')+filters(['All','To do','Completed'])+`<section class="panel" style="margin-top:18px">${tasks.map(taskRow).join('')||empty('checklist')}</section>`;}
function guests(){const options=`<select id="event-filter" aria-label="Filter guest attendance by event"><option value="">Overall attendance</option>${state.events.map(e=>`<option value="${escape(e.id)}" ${eventFilter===e.id?'selected':''}>${escape(e.name)}</option>`).join('')}</select><button class="button" data-action="export-guests">↓ Export CSV</button>`;const rows=state.guests.filter(matches).filter(g=>filter==='All'||(eventFilter?g.attendances?.[eventFilter]||'considered':g.status)===filter.toLowerCase());return title('The people who make it special.','Manage your guest list and track attendance separately for each celebration.')+toolbar('guests','Search guests…',options)+filters(['All','Confirmed','Invited','Tentative','Declined'])+`<section class="panel table-wrap" style="margin-top:18px"><table class="data-table"><thead><tr><th>GUEST</th><th>FAMILY / SIDE</th><th>${eventFilter?'EVENT RSVP':'OVERALL RSVP'}</th><th>DIETARY NOTES</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(g=>`<tr><td>${escape(g.name)}<br><small class="hint">${escape(g.email||'')}</small></td><td>${escape(g.side||'Both')}</td><td>${badge(eventFilter?g.attendances?.[eventFilter]||'considered':g.status)}</td><td>${escape(g.menu_restrictions||'—')}</td><td>${actions('guests',g.id)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('guest list')}</section>`;}
function budget(){const planned=state.budget.reduce((a,b)=>a+Number(b.total),0),available=Number(state.settings.budget)-planned;return title('More memories. Less money stress.','Keep track of your estimates and payments, across every celebration.')+`<div class="budget-total"><div><h2>Your wedding budget</h2><p>${available<0?'Over your budget by':'Available to plan'} ${money(Math.abs(available))}</p></div><strong>${money(state.settings.budget)}</strong><button class="button" data-action="settings">Edit budget</button></div>`+toolbar('budget','Search expenses…')+`<section class="panel table-wrap"><table class="data-table"><thead><tr><th>EXPENSE</th><th>CATEGORY</th><th>PLANNED TOTAL</th><th>PAID</th><th>REMAINING</th><th>ACTIONS</th></tr></thead><tbody>${state.budget.filter(matches).map(b=>`<tr><td>${escape(b.name)}<br><small class="hint">${escape(eventName(b.wedding_event_id))}${b.pricing_type==='per_person'?' · per-person rate':''}</small></td><td>${escape(b.category||'Other')}</td><td>${money(b.total)}</td><td>${money(b.paid)}</td><td>${money(Math.max(0,Number(b.total)-Number(b.paid)))}</td><td>${actions('budget',b.id)}</td></tr>`).join('')}</tbody></table>${state.budget.length?'':empty('budget')}</section>`;}
function vendors(){return title('Your dream team, coming together.','Keep your vendor shortlist, contact details, and booking progress in one place.')+toolbar('vendors','Search vendors…')+filters(['All','Shortlisted','Contacted','Booked'])+`<div class="cards" style="margin-top:20px">${state.vendors.filter(matches).filter(v=>filter==='All'||v.status===filter).map(v=>`<article class="vendor-card">${badge(v.status)}<h2>${escape(v.name)}</h2><p>${escape(v.category||'Wedding vendor')} · ${escape(eventName(v.wedding_event_id))}<br>${escape(v.contact||'Add contact details')}</p><p>${escape(v.notes||'')}</p><div class="card-actions"><button class="text-button" data-documents="${escape(v.id)}" data-document-entity="vendors" aria-label="Documents for ${escape(v.name)}">Documents${v.documents?.length?' ('+v.documents.length+')':''}</button>${actions('vendors',v.id)}</div></article>`).join('')||empty('vendor team')}</div>`;}
function events(){return title('One wedding. So many beautiful moments.','From mehendi to the reception, give each celebration its own plan.')+toolbar('events','Search celebrations…')+`<div class="cards">${[...state.events].sort((a,b)=>a.date.localeCompare(b.date)).filter(matches).map(e=>`<article class="event-card"><span class="pill warm">${date(e.date,{year:'numeric'})}</span><h2>${escape(e.name)}</h2><p>◷ ${escape(e.start_time||'Time to be decided')}<br>⌖ ${escape(e.venue||'Venue to be decided')}</p><p>${escape(e.notes||'')}</p><span class="pill">${state.guests.filter(g=>g.attendances?.[e.id]==='confirmed').length} guests confirmed</span><div class="card-actions">${actions('events',e.id)}</div></article>`).join('')||empty('celebrations')}</div>`;}
const field=(name,label,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${escape(value)}" ${attrs}></label>`;
const select=(name,label,values,current)=>`<label class="field">${label}<select name="${name}">${values.map(v=>{const pair=Array.isArray(v)?v:[v,v];return `<option value="${escape(pair[0])}" ${String(current??'')===String(pair[0])?'selected':''}>${escape(pair[1])}</option>`;}).join('')}</select></label>`;
const textarea=(name,label,value='')=>`<label class="field full">${label}<textarea name="${name}" maxlength="3000">${escape(value)}</textarea></label>`;
function settingsFields(s){return field('partner_one','Your name',s.partner_one,'text','required maxlength="250"')+field('partner_two','Your partner’s name',s.partner_two,'text','required maxlength="250"')+field('date','Wedding date',s.date,'date')+field('venue','Wedding location',s.venue,'text','maxlength="250"')+select('currency','Currency',['INR','USD','GBP','EUR','AED'],s.currency)+field('budget','Total wedding budget',s.budget,'number','min="0" step="0.01" required');}
function settings(){return title('Make this wedding yours.','The details that set the stage for your celebrations.')+(!live?`<div class="banner">You’re exploring sample data. Changes stay in this browser. Google sign-in and shared editing become available after the backend is configured.</div>`:'')+`<section class="panel"><form id="settings-form" class="settings-form"><div class="form-grid">${settingsFields(state.settings)}</div><button class="button primary" type="submit">Save wedding details</button></form></section><div class="toolbar"><button class="button" data-action="export">↓ Export wedding data</button>${!live?'<button class="button danger" data-action="reset">Reset sample wedding</button>':''}<button class="button" data-action="setup">Google sign-in setup</button><button class="button" data-action="research">Explore alternatives</button></div>`;}
function render(){
  $('navigation').innerHTML=views.map(([id,label,icon])=>`<a class="nav-item ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');
  $('page-label').textContent=views.find(v=>v[0]===page)?.[1]||'Overview';
  $('signin').innerHTML=state.user?'Sign out':'<span class="google-icon">G</span> Sign in with Google';
  $('account-name').innerHTML=state.user?`${escape(state.user.email)}<small>Shared wedding workspace</small>`:live?'Your wedding workspace<small>Sign in to get started</small>':'Demo workspace<small>Saved on this browser</small>';
  if(live)$('sync-status').textContent=state.user?'● Shared workspace':'● Sign in to sync';
  $('main').innerHTML=(!live?'<div class="demo-notice">INTERACTIVE DEMO <span>Sample wedding · edits stay in this browser</span></div>':'')+({overview,checklist,guests,budget,vendors,events,settings}[page]||overview)();
  if(live&&!state.user)$('main').innerHTML=title('Let’s plan your forever.','Sign in to open your wedding workspace.')+`<div class="panel onboarding"><span class="flower">✳</span><h2>Everyone in the same plan.</h2><p>Bring your celebrations, your people, and your ideas together.<br>${config.googleOnly?'Sign in with your Google account to begin.':'Sign in with Google or your existing account to begin.'}</p><button class="button primary" data-action="login">Open wedding workspace</button></div>`;
  const input=$('search');if(input)input.oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};
  if($('event-filter'))$('event-filter').onchange=e=>{eventFilter=e.target.value;render();};
  if($('settings-form'))$('settings-form').onsubmit=async e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.budget=Number(r.budget);r.date=r.date||null;if(await change('settings',r,state.settings.id))toast('Your wedding details are saved.');};
}
function edit(entity,id){const current=id?state[entity].find(x=>x.id===id):{},s=current||{};const eventOptions=[['','All celebrations'],...state.events.map(e=>[e.id,e.name])];let html='';
  if(entity==='tasks')html='<p class="hint full">Use Documents on a saved task to attach invoices, contracts, or other files.</p>'+field('title','What needs to be done?',s.title,'text','required maxlength="250"')+field('due_date','Due date',s.due_date,'date')+field('assignee','Assigned to',s.assignee,'text','maxlength="120"')+select('priority','Priority',['Normal','High'],s.priority)+select('wedding_event_id','Celebration',eventOptions,s.wedding_event_id);
  if(entity==='guests')html=field('name','Guest name',s.name,'text','required maxlength="250"')+field('email','Email',s.email,'email','maxlength="250"')+field('phone','Phone',s.phone,'tel','maxlength="60"')+select('side','Family / side',['Both',`${state.settings.partner_one||'Partner one'}’s side`,`${state.settings.partner_two||'Partner two'}’s side`],s.side)+select('status','Overall RSVP',['invited','confirmed','tentative','declined','considered'],s.status)+field('menu_restrictions','Dietary notes',s.menu_restrictions,'text','maxlength="500"')+textarea('special_requests','Other notes',s.special_requests)+`<div class="field full"><b>Attendance at each celebration</b><span class="hint">Each event has its own RSVP. “Considered” means not yet invited.</span></div>`+state.events.map(e=>select('event:'+e.id,e.name,['considered','invited','confirmed','tentative','declined'],s.attendances?.[e.id]||'considered')).join('');
  if(entity==='budget')html=field('name','Expense name',s.name,'text','required maxlength="250"')+field('category','Category',s.category,'text','maxlength="120"')+field('amount','Estimate / per-person rate',s.amount??'','number','min="0.01" step="0.01" required')+select('pricing_type','Pricing',['fixed','per_person'],s.pricing_type||'fixed')+field('paid','Amount paid so far',s.paid??0,'number','min="0" step="0.01" required')+select('wedding_event_id','Celebration',eventOptions,s.wedding_event_id);
  if(entity==='vendors')html='<p class="hint full">Use Documents on a saved vendor card to attach quotes, contracts, invoices, or menus.</p>'+field('name','Vendor name',s.name,'text','required maxlength="120"')+field('category','Category',s.category,'text','maxlength="250"')+field('contact','Contact details',s.contact,'text','maxlength="250"')+select('status','Booking status',['Shortlisted','Contacted','Booked'],s.status)+select('wedding_event_id','Celebration',eventOptions,s.wedding_event_id)+textarea('notes','Notes',s.notes);
  if(entity==='events')html=field('name','Celebration name',s.name,'text','required maxlength="120"')+field('date','Date',s.date,'date','required')+field('start_time','Start time',s.start_time,'time')+field('venue','Venue',s.venue,'text','maxlength="250"')+textarea('notes','Notes',s.notes);
  modal(`${id?'Edit':'Add'} ${entity==='tasks'?'task':entity==='budget'?'expense':entity==='events'?'celebration':entity.replace(/s$/,'')}`,`<form id="record-form"><div class="form-grid">${html}</div><div class="form-actions">${id?`<button type="button" class="button danger" id="remove-record">Remove</button>`:''}<button type="button" class="button" id="cancel-record">Cancel</button>${['tasks','vendors'].includes(entity)?'<button type="submit" class="button" id="save-and-documents">Save & attach documents</button>':''}<button type="submit" class="button primary">Save ${entity==='events'?'celebration':'changes'}</button></div></form>`);
  $('cancel-record').onclick=closeModal;if($('remove-record'))$('remove-record').onclick=()=>remove(entity,id);
  $('record-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;const record=Object.fromEntries(new FormData(e.target));const extras={};if(record.wedding_event_id==='')record.wedding_event_id=null;if(record.due_date==='')record.due_date=null;if(entity==='budget'){record.amount=Number(record.amount);extras.paid=Number(record.paid);delete record.paid;}if(entity==='guests'){extras.attendances={};Object.keys(record).filter(k=>k.startsWith('event:')).forEach(k=>{extras.attendances[k.slice(6)]=record[k];delete record[k];});}const manageDocuments=e.submitter?.id==='save-and-documents';const previousIds=new Set(state[entity]?.map(item=>item.id));if(await change(entity,record,id,extras)){closeModal();toast('Saved. One more detail taken care of.');if(manageDocuments){const saved=id?state[entity].find(item=>item.id===id):state[entity].find(item=>!previousIds.has(item.id));if(saved)recordDocuments(entity,saved.id);}}else submit.disabled=false;};
}
const documentTypes='.pdf,.docx,.xlsx,.pptx,.txt,.csv,.jpg,.jpeg,.png,.webp';
const fileSize=bytes=>bytes>=1024*1024?(bytes/(1024*1024)).toFixed(1)+' MB':Math.max(1,Math.ceil(bytes/1024))+' KB';
async function reloadDocuments(entity,recordId,expectedGeneration=dialogGeneration){
  state=await api(encodeURIComponent(slug)+'/planner');render();
  if(dialogGeneration!==expectedGeneration||!$('dialog').open)return;
  if(state[entity].some(record=>record.id===recordId))recordDocuments(entity,recordId);
  else{closeModal();toast('This item was removed by a collaborator.');}
}
function recordDocuments(entity,recordId){
  const record=state[entity].find(item=>item.id===recordId);if(!record)return;
  const documents=record.documents||[];
  modal(entity==='tasks'?'Task documents':'Vendor documents',`<p class="document-task-title">${escape(record.title||record.name)}</p><p class="hint">Private to your wedding’s collaborators. PDF, Word, Excel, PowerPoint, text, CSV, and images. Up to 3 MB each · 10 files per item.</p>${!live?'<div class="banner">Document uploads are available in your signed-in wedding workspace.</div>':`<form id="document-upload-form" class="document-upload"><label class="field" for="document-file">Choose a document<input id="document-file" name="file" type="file" accept="${documentTypes}" required></label><button class="button primary" id="document-upload-button" type="submit">Upload document</button><p id="document-upload-status" class="hint" role="status" aria-live="polite"></p></form>`}<div class="document-list">${documents.length?documents.map(d=>`<div class="document-row"><div class="document-info"><b>${escape(d.file_name)}</b><small>${fileSize(d.byte_size)} · Added ${date(d.created_at,{year:'numeric'})}</small></div><a class="text-button" href="/api/${encodeURIComponent(slug)}/planner/${entity}/${encodeURIComponent(recordId)}/documents/${encodeURIComponent(d.id)}" download="${escape(d.file_name)}">Download</a><button class="text-button" data-remove-document="${escape(d.id)}">Remove</button></div>`).join(''):'<div class="document-empty">No documents yet. Add a quote, invoice, menu, or contract.</div>'}</div>${live?'<button class="text-button" id="document-refresh">Refresh documents</button>':''}`);
  if(!live)return;
  const panelGeneration=dialogGeneration;let uploading=false;
  $('document-upload-form').onsubmit=async event=>{
    event.preventDefault();if(uploading)return;
    const file=$('document-file').files[0];if(!file)return;
    const status=$('document-upload-status');
    if(!file.size||file.size>3*1024*1024){status.textContent='Choose a file between 1 byte and 3 MB.';return;}
    if(!documentTypes.split(',').includes('.'+file.name.split('.').pop().toLowerCase())){status.textContent='This file type is not supported. Choose a document or image listed above.';return;}
    if(documents.length>=10){status.textContent='This item already has 10 documents. Remove one first.';return;}
    uploading=true;$('document-upload-button').disabled=true;$('document-file').disabled=true;status.textContent='Uploading '+file.name+'…';
    const body=new FormData();body.append('file',file);body.append('lock_version',String(record.lock_version));
    try{await api(encodeURIComponent(slug)+'/planner/'+entity+'/'+encodeURIComponent(recordId)+'/documents',{method:'POST',body});await reloadDocuments(entity,recordId,panelGeneration);toast('Document attached.');}
    catch(error){if(error.status===409){try{await reloadDocuments(entity,recordId,panelGeneration);}catch{}toast(error.message);}else if(dialogGeneration===panelGeneration&&$('document-upload-status'))$('document-upload-status').textContent=error.message;}
    finally{uploading=false;if(dialogGeneration===panelGeneration){if($('document-upload-button'))$('document-upload-button').disabled=false;if($('document-file'))$('document-file').disabled=false;}}
  };
  $('document-refresh').onclick=async()=>{try{await reloadDocuments(entity,recordId);}catch(error){toast(error.message);}};
  $('dialog-body').querySelectorAll('[data-remove-document]').forEach(button=>button.onclick=()=>{
    if(uploading)return;
    const doc=documents.find(d=>d.id===button.dataset.removeDocument);
    modal('Remove document?',`<p class="hint">Remove ${escape(doc.file_name)} from this item? Keep a downloaded copy if you need it later.</p><div class="form-actions"><button class="button" id="keep-document">Keep document</button><button class="button danger" id="confirm-remove-document">Remove document</button></div>`);
    const removalGeneration=dialogGeneration;
    $('keep-document').onclick=()=>recordDocuments(entity,recordId);
    $('confirm-remove-document').onclick=async event=>{
      event.target.disabled=true;
      try{await api(encodeURIComponent(slug)+'/planner/'+entity+'/'+encodeURIComponent(recordId)+'/documents/'+encodeURIComponent(doc.id),{method:'DELETE',body:JSON.stringify({lock_version:record.lock_version})});await reloadDocuments(entity,recordId,removalGeneration);toast('Document removed.');}
      catch(error){try{await reloadDocuments(entity,recordId,removalGeneration);}catch{}toast(error.message);}
    };
  });
}
function remove(entity,id){const record=state[entity].find(x=>x.id===id);modal('Remove this item?',`<p class="hint">Remove ${escape(record?.name||record?.title||'this item')}? ${['tasks','vendors'].includes(entity)&&record?.documents?.length?'Its attached documents will also be removed. ' : ''}${entity==='events'?'Its attendance records will also be removed. Tasks, vendors, and expenses will be kept without an event.':''}</p><div class="form-actions"><button class="button" id="cancel-remove">Keep it</button><button class="button danger" id="confirm-remove">Remove item</button></div>`);$('cancel-remove').onclick=closeModal;$('confirm-remove').onclick=async()=>{if(await change(entity,{},id,{},true)){closeModal();toast('Item removed.');}};}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function exportGuests(){const cell=v=>{let text=String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};const events=state.events;const headers=['Name','Email','Phone','Side','Overall RSVP','Dietary notes',...events.map(e=>e.name+' RSVP')];const rows=state.guests.map(g=>[g.name,g.email,g.phone,g.side,g.status,g.menu_restrictions,...events.map(e=>g.attendances?.[e.id]||'considered')]);download('wedding-guests.csv',[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Guest list exported.');}
function setup(){modal('Connect Google sign-in',`<p class="hint">${live?'Your shared workspace':'This preview uses sample data. The shared version'} uses LibreWeddingPlanner’s Rails backend.</p><ol class="hint"><li>Open <a class="inline-link" href="https://console.cloud.google.com/auth/overview" target="_blank" rel="noopener">Google Auth Platform</a> and create a project.</li><li>Configure branding and choose an External audience, then add your support email. Basic Google sign-in does not require a test-user list.</li><li>Create an OAuth client with application type <b>Web application</b>.</li><li>Add <code>http://localhost</code> and <code>http://localhost:8080</code> under <b>Authorized JavaScript origins</b> for local testing, plus your exact HTTPS origin when deployed. Origins have no path.</li><li>Set <code>GOOGLE_CLIENT_ID</code> on the backend, then recreate its container. This popup sign-in flow doesn’t need a client secret or redirect URI.</li></ol><p class="hint">You can share the client ID with me to finish configuration. Don’t share your Google password or a service-account private key.</p><a class="button" href="https://developers.google.com/identity/gsi/web/guides/get-google-api-clientid" target="_blank" rel="noopener">Google’s setup guide ↗</a>`);}
function research(){modal('Existing wedding planners',`<p class="hint">We’re adapting <a class="inline-link" href="https://libreweddingplanner.org/" target="_blank" rel="noopener">LibreWeddingPlanner</a>, an AGPL open-source planner with guests, expenses, RSVPs, and shared team access. Our changes add this interface, separate celebrations, and Google sign-in.</p><p class="hint">Ready-made alternatives: <a href="https://wedsites.com/pricing/" target="_blank" rel="noopener">WedSites</a> (Google sign-in, team permissions, multi-event RSVPs), <a href="https://itsmy.wedding/tools" target="_blank" rel="noopener">itsmy.wedding</a> (Indian wedding tools and family collaboration), and <a href="https://www.weddingwire.in/my-wedding-planner" target="_blank" rel="noopener">WeddingWire India</a> (planning tools and partner linking).</p><p class="hint">The React/Supabase repository <a href="https://github.com/eyalsegev123/WeddingPlanner" target="_blank" rel="noopener">WeddingPlanner</a> has similar features, but had no license file when reviewed. We haven’t reused its code.</p>`);}
async function share(){if(!live||!state.user){modal('Bring your people together',`<p class="hint">Invitations and shared editing need a signed-in workspace. This demo saves only on your browser, so copying its link won’t share your edits.</p><p class="hint">Once the backend is connected, you can invite your partner, family, or planner by email. Invited members have full access to this wedding, matching LibreWeddingPlanner’s team model.</p><button class="button primary" id="setup-share">Set up Google sign-in</button>`);$('setup-share').onclick=setup;return;}
  modal('Your wedding team',`<div class="banner">Team members can view and edit the entire wedding. Only invite people you trust with your guest list and budget.</div>${state.members.map(m=>`<div class="team-row"><div>${escape(m.email)}<small>${escape(m.status)}</small></div>${m.deletable?`<button class="text-button danger" data-member="${escape(m.id)}">Remove</button>`:'<span class="pill">You</span>'}</div>`).join('')}<form id="invite-form" style="margin-top:22px">${field('email',config.googleInvites?'Collaborator’s Google email':'Invite by email','','email','required')}<button class="button primary" type="submit">${config.googleInvites?'Add collaborator':'Send invitation'}</button>${config.googleInvites?'<p class="hint">Add their Gmail or Google Workspace email, then share the workspace link. They join by signing in with that exact Google account. No email is sent.</p>':''}</form><div class="form-actions"><button class="button" id="copy-link">Copy workspace link</button></div>`);
  $('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/?wedding='+encodeURIComponent(slug));toast('Workspace link copied. Invite members by email before sharing.');}catch{toast('Clipboard access is unavailable. Copy the address from your browser.');}};
  $('invite-form').onsubmit=async e=>{e.preventDefault();e.target.querySelector('button').disabled=true;try{await api(encodeURIComponent(slug)+'/memberships',{method:'POST',body:JSON.stringify({user:{email:new FormData(e.target).get('email')}})});closeModal();await refresh();toast(config.googleInvites?'Collaborator added. Share the workspace link so they can sign in with Google.':'Invitation created. Delivery depends on the configured email service.');}catch(err){toast(err.message);e.target.querySelector('button').disabled=false;}};
}
async function login(){if(!live){setup();return;}modal('Open your wedding workspace',`<form id="login-form"><p class="hint">Use your wedding’s address name. New couples can create a workspace using Google.</p>${field('slug','Wedding address name',slug,'text','required pattern="[a-z0-9-]+" maxlength="80"')}${config.googleOnly?'':field('email','Email','','email')+field('password','Password','','password')+'<button class="button" type="submit">Sign in with password</button>'}<label class="field" style="margin-top:20px"><span><input type="checkbox" id="create-wedding"> Create a new wedding with Google</span></label><div id="google-button"></div><p id="google-message" class="hint">Loading Google sign-in…</p></form>`);
  const success=async weddingSlug=>{slug=weddingSlug;closeModal();state.user={email:'Signed in'};await refresh();history.replaceState(null,'','?wedding='+encodeURIComponent(slug)+'#overview');toast('Welcome to your shared wedding.');};
  const weddingAddress=()=>{const input=$('login-form').elements.slug;input.value=input.value.trim().toLowerCase();return input.reportValidity()?input.value:null;};
  $('login-form').onsubmit=async e=>{e.preventDefault();if(config.googleOnly)return;try{await fetch('/api/token',{credentials:'same-origin'});const d=Object.fromEntries(new FormData(e.target));const weddingSlug=weddingAddress();if(!weddingSlug)return;await api(encodeURIComponent(weddingSlug)+'/users/sign_in',{method:'POST',body:JSON.stringify({user:{email:d.email,password:d.password}})});await success(weddingSlug);}catch(err){toast(err.message);}};
  async function configureGoogle(message='Sign in using the email address invited to this wedding, or select Create a new wedding to start.'){
    try{await fetch('/api/token',{credentials:'same-origin'});const g=await api('google/config');if(!$('dialog').open||!$('google-button'))return;if(!g.client_id){$('google-message').textContent='Google sign-in needs a client ID on the backend. Password login is available for existing accounts.';return;}
      if(!window.google?.accounts){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=reject;document.head.append(script);});}
      if(!$('dialog').open||!$('google-button'))return;
      window.google.accounts.id.initialize({client_id:g.client_id,nonce:g.nonce,callback:async response=>{const weddingSlug=weddingAddress();if(!weddingSlug)return;try{await api('google/sign_in',{method:'POST',body:JSON.stringify({credential:response.credential,slug:weddingSlug,create_wedding:$('create-wedding').checked})});await success(weddingSlug);}catch(err){toast(err.message);await configureGoogle(err.message);}}});$('google-button').replaceChildren();window.google.accounts.id.renderButton($('google-button'),{theme:'outline',size:'large',text:'signin_with',width:300});$('google-message').textContent=message;
    }catch{if($('google-message'))$('google-message').textContent='Google sign-in could not load. Check the backend connection.';}
  }
  await configureGoogle();
}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.documents)recordDocuments(el.dataset.documentEntity,el.dataset.documents);if(el.dataset.add)edit(el.dataset.add);if(el.dataset.edit)edit(el.dataset.edit,el.dataset.id);if(el.dataset.delete)remove(el.dataset.delete,el.dataset.id);if(el.dataset.filter){filter=el.dataset.filter;render();}if(el.dataset.toggle){const task=state.tasks.find(t=>t.id===el.dataset.toggle);await change('tasks',{completed_at:task.completed_at?null:new Date().toISOString()},task.id);}if(el.dataset.member){const member=state.members.find(m=>m.id===el.dataset.member);modal('Remove team member?',`<p class="hint">${escape(member.email)} will lose access to this wedding.</p><div class="form-actions"><button class="button" id="keep-member">Keep access</button><button class="button danger" id="remove-member">Remove access</button></div>`);$('keep-member').onclick=closeModal;$('remove-member').onclick=async()=>{try{await api(encodeURIComponent(slug)+'/memberships/'+encodeURIComponent(member.id),{method:'DELETE'});closeModal();await refresh();toast('Team member removed.');}catch(err){toast(err.message);}};}const action=el.dataset.action;if(action==='share')share();if(action==='settings')location.hash='settings';if(action==='setup')setup();if(action==='research')research();if(action==='login')login();if(action==='export-guests')exportGuests();if(action==='export')download('wedding-plan.json',JSON.stringify(state,null,2),'application/json');if(action==='reset'){modal('Reset the sample wedding?',`<p class="hint">This removes your demo edits in this browser and restores the original sample. Export your wedding data first if you want to keep it.</p><div class="form-actions"><button class="button" id="keep-demo">Keep my edits</button><button class="button danger" id="reset-demo">Reset sample</button></div>`);$('keep-demo').onclick=closeModal;$('reset-demo').onclick=()=>{state=sample();persist();render();closeModal();toast('Sample wedding restored.');};}});
$('main').addEventListener('change',async e=>{if(e.target.dataset.toggle){const task=state.tasks.find(t=>t.id===e.target.dataset.toggle);e.target.disabled=true;if(!await change('tasks',{completed_at:e.target.checked?new Date().toISOString():null},task.id))render();}});
$('share').onclick=share;$('account').onclick=()=>live?share():setup;
$('signin').onclick=async()=>{if(state.user){try{await api(encodeURIComponent(slug)+'/users/sign_out',{method:'DELETE'});state.user=null;render();}catch(e){toast(e.message);}}else login();};
